export const EDGES=[];for(let a=0;a<6;a++)for(let b=a+1;b<6;b++)EDGES.push([a,b]);
export function edgeIndex(a,b){return EDGES.findIndex(e=>e[0]===Math.min(a,b)&&e[1]===Math.max(a,b));}
export function triangle(board,player){for(let a=0;a<6;a++)for(let b=a+1;b<6;b++)for(let c=b+1;c<6;c++){let ids=[edgeIndex(a,b),edgeIndex(b,c),edgeIndex(a,c)];if(ids.every(i=>board[i]===player))return ids;}return null;}
export function safeMoves(board,p){return EDGES.map((_,i)=>i).filter(i=>{if(board[i])return false;board[i]=p;let ok=!triangle(board,p);board[i]=0;return ok;});}
export function chooseMove(board,p){const safe=safeMoves(board,p);if(!safe.length)return board.findIndex(v=>!v);let nodes=0;const memo=new Map();function search(b,turn,depth,alpha,beta){nodes++;const moves=safeMoves(b,turn);if(!moves.length)return turn===p?-1000-depth:1000+depth;if(!depth||nodes>18000)return safeMoves(b,p).length-safeMoves(b,3-p).length;const key=b.join('')+turn+depth;if(memo.has(key))return memo.get(key);let value=turn===p?-Infinity:Infinity;let cut=false;for(const i of moves){b[i]=turn;const v=search(b,3-turn,depth-1,alpha,beta);b[i]=0;if(turn===p){value=Math.max(value,v);alpha=Math.max(alpha,v);}else{value=Math.min(value,v);beta=Math.min(beta,v);}if(beta<=alpha){cut=true;break;}}if(!cut)memo.set(key,value);return value;}const depth=board.filter(v=>!v).length<9?7:3;let best=-Infinity,options=[];for(const i of safe){board[i]=p;const score=search(board,3-p,depth,-Infinity,Infinity);board[i]=0;if(score>best){best=score;options=[i];}else if(score===best)options.push(i);}return options[Math.floor(Math.random()*options.length)];}
